-        let result = self.backend.execute(self.jobs[slot].request);
-        self.jobs[slot].state = if result.is_ok() {
-            JobState::Succeeded
-        } else {
-            JobState::Failed
-        };
-        self.jobs[slot].error = result.err();
-        if usize::from(self.notice_count) < MAX_NOTICES {
