+#[derive(Clone, Copy)]
+struct Frame {
+    len: usize,
+    bytes: [u8; MAX_FRAME_SIZE],
+}
+
+impl Frame {
+    const fn empty() -> Self {
+        Self {
+            len: 0,
+            bytes: [0; MAX_FRAME_SIZE],
+        }
+    }
+}
