+struct HostRootfs {
+    descriptor: usize,
+}
+
+impl BaseReader for HostRootfs {
+    fn read_at(&mut self, offset: u64, output: &mut [u8]) -> Result<(), VfsError> {
+        let result = unsafe {
+            syscall4(
+                SYS_PREAD64,
+                self.descriptor,
+                output.as_mut_ptr() as usize,
+                output.len(),
+                offset as usize,
+            )
+        };
+        if result == output.len() as isize {
+            Ok(())
+        } else {
+            Err(VfsError::Io)
+        }
+    }
+}
