+#![no_std]
+
+mod cgroup;
+
+use ginux_devices::{DeviceKind, DeviceView};
+use ginux_process::{TaskState, TaskView};
+
+pub use cgroup::CgroupFs;
+
+#[derive(Clone, Copy, Debug, Eq, PartialEq)]
+pub enum ViewError {
+    NotFound,
+    PermissionDenied,
+    ReadOnly,
+    BufferTooSmall,
+    InvalidPath,
+    AlreadyExists,
+    LimitExceeded,
+    Busy,
+}
+
+#[derive(Clone, Copy)]
+pub struct MemoryView {
+    pub total_bytes: u64,
+    pub available_bytes: u64,
+}
+
+#[derive(Clone, Copy)]
+pub struct IdentityView<'a> {
+    pub hostname: &'a [u8],
+    pub machine_id: &'a [u8],
+    pub boot_id: &'a [u8],
+}
+
+#[derive(Clone, Copy)]
+pub struct NamespaceView {
+    pub mount: u64,
+    pub pid: u64,
+    pub uts: u64,
+    pub cgroup: u64,
+}
+
+pub struct IdentityFs<'a> {
+    tasks: &'a [TaskView],
+    identity: IdentityView<'a>,
+    namespaces: NamespaceView,
+}
+
+impl<'a> IdentityFs<'a> {
+    pub const fn new(
+        tasks: &'a [TaskView],
+        identity: IdentityView<'a>,
+        namespaces: NamespaceView,
+    ) -> Self {
+        Self {
+            tasks,
+            identity,
+            namespaces,
+        }
+    }
+
+    pub fn read(&self, path: &[u8], output: &mut [u8]) -> Result<usize, ViewError> {
+        let mut writer = Writer::new(output);
+        match path {
+            b"/etc/machine-id" => writer.bytes(self.identity.machine_id)?,
+            b"/etc/hostname" => writer.bytes(self.identity.hostname)?,
+            _ => return Err(ViewError::NotFound),
+        }
+        writer.byte(b'\n')?;
+        Ok(writer.len)
+    }
+
+    pub fn readlink(&self, path: &[u8], output: &mut [u8]) -> Result<usize, ViewError> {
+        let (pid, leaf) = parse_task_path(path, 0)?;
+        if !self.tasks.iter().any(|task| task.id.pid == pid) {
+            return Err(ViewError::NotFound);
+        }
+        let (name, id) = match leaf {
+            b"ns/mnt" => (b"mnt".as_slice(), self.namespaces.mount),
+            b"ns/pid" => (b"pid".as_slice(), self.namespaces.pid),
+            b"ns/uts" => (b"uts".as_slice(), self.namespaces.uts),
+            b"ns/cgroup" => (b"cgroup".as_slice(), self.namespaces.cgroup),
+            _ => return Err(ViewError::NotFound),
+        };
+        let mut writer = Writer::new(output);
+        writer.bytes(name)?;
+        writer.bytes(b":[")?;
+        writer.decimal(id)?;
+        writer.byte(b']')?;
+        Ok(writer.len)
+    }
+
+    pub fn write(&self, _path: &[u8], _input: &[u8]) -> Result<usize, ViewError> {
+        Err(ViewError::ReadOnly)
+    }
+}
+
+#[derive(Clone, Copy)]
+pub struct MountView<'a> {
+    pub source: &'a [u8],
+    pub target: &'a [u8],
+    pub filesystem: &'a [u8],
+    pub options: &'a [u8],
+}
+
+pub struct ProcFs<'a> {
+    tasks: &'a [TaskView],
+    self_pid: u32,
+    uptime_ns: u64,
+    memory: MemoryView,
+    identity: IdentityView<'a>,
+    mounts: &'a [MountView<'a>],
+}
+
+pub struct SysFs<'a> {
+    devices: &'a [DeviceView],
+    cpu_count: u32,
+}
+
+impl<'a> SysFs<'a> {
+    pub const fn new(devices: &'a [DeviceView], cpu_count: u32) -> Self {
+        Self { devices, cpu_count }
+    }
+
+    pub fn list_devices(&self, output: &mut [DeviceView]) -> usize {
+        let count = core::cmp::min(output.len(), self.devices.len());
+        output[..count].copy_from_slice(&self.devices[..count]);
+        count
+    }
+
+    pub fn read(&self, path: &[u8], output: &mut [u8]) -> Result<usize, ViewError> {
+        let mut writer = Writer::new(output);
+        if path == b"/sys/devices/system/cpu/online" {
+            if self.cpu_count == 0 {
+                return Err(ViewError::NotFound);
+            }
+            writer.byte(b'0')?;
+            if self.cpu_count > 1 {
+                writer.byte(b'-')?;
+                writer.decimal(u64::from(self.cpu_count - 1))?;
+            }
+            writer.byte(b'\n')?;
+            return Ok(writer.len);
+        }
+        let rest = path
+            .strip_prefix(b"/sys/class/")
+            .ok_or(ViewError::InvalidPath)?;
+        let first = rest
+            .iter()
+            .position(|byte| *byte == b'/')
+            .ok_or(ViewError::InvalidPath)?;
+        let class = &rest[..first];
+        let remaining = &rest[first + 1..];
+        let second = remaining
+            .iter()
+            .position(|byte| *byte == b'/')
+            .ok_or(ViewError::InvalidPath)?;
+        let name = &remaining[..second];
+        let leaf = &remaining[second + 1..];
+        let device = self
+            .devices
+            .iter()
+            .find(|device| device.name.as_bytes() == name && device_class(device.kind) == class)
+            .ok_or(ViewError::NotFound)?;
+        match leaf {
+            b"dev" if device.kind != DeviceKind::Network => {
+                writer.decimal(u64::from(device.major))?;
+                writer.byte(b':')?;
+                writer.decimal(u64::from(device.minor))?;
+                writer.byte(b'\n')?;
+            }
+            b"type" if device.kind == DeviceKind::Network => {
+                writer.bytes(b"1\n")?;
+            }
+            b"uevent" => {
+                writer.bytes(b"DEVNAME=")?;
+                writer.bytes(device.name.as_bytes())?;
+                writer.bytes(b"\nDEVTYPE=")?;
+                writer.bytes(device_type(device.kind))?;
+                writer.byte(b'\n')?;
+            }
+            _ => return Err(ViewError::NotFound),
+        }
+        Ok(writer.len)
+    }
+
+    pub fn write(&self, _path: &[u8], _input: &[u8]) -> Result<usize, ViewError> {
+        Err(ViewError::ReadOnly)
+    }
+}
+
+fn device_class(kind: DeviceKind) -> &'static [u8] {
+    match kind {
+        DeviceKind::Block => b"block",
+        DeviceKind::Network => b"net",
+        DeviceKind::Console => b"tty",
+        DeviceKind::Null | DeviceKind::Zero | DeviceKind::Random => b"misc",
+    }
+}
