+            .checked_mul(phnum)
+            .and_then(|size| phoff.checked_add(size))
+            .ok_or(LoadError::InvalidProgramHeaders)?;
+        if table_size > elf.len() {
+            return Err(LoadError::InvalidProgramHeaders);
+        }
